/**
 * Requires the archive password, which is verified server-side.
 * @summary Delete an archived plant
 */
export const DeletePlantParams = zod.object({
  "id": zod.coerce.number()
})

export const DeletePlantBody = zod.object({
  "password": zod.string().describe('Archive password required to delete an entry.')
})

export const DeletePlantResponse = zod.void()


/**
 * Password-protected maintenance endpoint used to recompress stored photos and backfill new fact-sheet fields on existing entries. The archive password is verified server-side.
 * @summary Update fields of an archived plant (maintenance)
 */
